#include <iostream>
class MyClass {
public:
    MyClass() { std::cout << "Default constructor called" << std::endl; }
};

int main() {
    MyClass obj; // default-initialized object, default constructor invoked
    int arr[3]; // array of integers, elements are default-initialized to indeterminate values
    int& ref; // invalid: references must be initialized explicitly
    return 0;
}
